using System;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
public static class ProjectMapEditSessionTests {
 static void Check(bool ok,string message){if(!ok)throw new Exception("SESSION_FAIL "+message);}
 static object Call(object value,string method,params object[] args){try{return value.GetType().GetMethod(method).Invoke(value,args);}catch(TargetInvocationException ex){throw ex.InnerException;}}
 static T Prop<T>(object value,string name){return (T)value.GetType().GetProperty(name).GetValue(value,null);}
 public static void Run(){
  var type=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("ProjectMapEditSession")).FirstOrDefault(t=>t!=null);Check(type!=null,"session type exists");
  string source=ProjectMapStore.FindRoot(Application.dataPath);string root=Path.Combine(source,"artifacts/session-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(root,".git"));Directory.CreateDirectory(Path.Combine(root,"unity/YeongtongTaxi/ProjectSettings"));File.WriteAllText(Path.Combine(root,"unity/YeongtongTaxi/ProjectSettings/ProjectVersion.txt"),"fixture");Directory.CreateDirectory(Path.GetDirectoryName(Path.Combine(root,ProjectMapStore.RelativePath)));File.Copy(ProjectMapStore.SourcePath(source),Path.Combine(root,ProjectMapStore.RelativePath));
  object session=type.GetMethod("Open").Invoke(null,new object[]{root});
  try{
   var document=Prop<RoadMapDocument>(session,"Document");var target=document.scene.objects.First(o=>o.kind=="building"&&o.enabled);string id=target.id;string before=JsonUtility.ToJson(Call(session,"GetObject",id));string other=JsonUtility.ToJson(document.scene.objects.First(o=>o.id!=id));string baseline=JsonUtility.ToJson(Prop<MapData>(session,"Baseline"));string disk=File.ReadAllText(ProjectMapStore.SourcePath(root));
   bool vertexRejected=false;try{Call(session,"SetVertex",id,0,target.points[1].V());}catch(ArgumentException){vertexRejected=true;}Check(vertexRejected&&JsonUtility.ToJson(Call(session,"GetObject",id))==before&&!Prop<bool>(session,"Dirty"),"invalid vertex topology rejected without session change");Action<string[]> badListener=ids=>{throw new InvalidOperationException("render failure fixture");};type.GetEvent("Changed").AddEventHandler(session,badListener);bool listenerRejected=false;try{Call(session,"Transform",id,Vector3.zero,0f,Vector2.one,1.1f);}catch(InvalidOperationException){listenerRejected=true;}finally{type.GetEvent("Changed").RemoveEventHandler(session,badListener);}Check(listenerRejected&&JsonUtility.ToJson(Call(session,"GetObject",id))==before&&!Prop<bool>(session,"Dirty"),"notification failure rolls back object and dirty state");var geometry=(ProjectMapObject)Call(session,"GetObject",id);float cx=geometry.points.Average(p=>p.x),cz=geometry.points.Average(p=>p.z);float firstX=geometry.points[0].x,firstZ=geometry.points[0].z;Call(session,"Transform",id,new Vector3(5,0,7),90f,new Vector2(2,3),1f);var moved=(ProjectMapObject)Call(session,"GetObject",id);Check(Mathf.Abs(moved.points[0].x-(cx+3*(firstZ-cz)+5))<.01f&&Mathf.Abs(moved.points[0].z-(cz-2*(firstX-cx)+7))<.01f,"nonuniform XZ scale and horizontal yaw follow expected geometry");Undo.FlushUndoRecordObjects();Call(session,"WriteDraft");Undo.PerformUndo();Check(!Prop<bool>(session,"Dirty"),"transform undo restores clean geometry");Call(session,"WriteDraft");Check(!Prop<bool>(session,"HasDraft"),"undo to clean removes owned draft instead of resurrecting edit");Call(session,"Transform",id,new Vector3(0,0,0),0f,new Vector2(1,1),1.1f);Check(Prop<bool>(session,"Dirty"),"height marks dirty");Check(File.ReadAllText(ProjectMapStore.SourcePath(root))==disk,"edit does not save disk");Undo.FlushUndoRecordObjects();Undo.PerformUndo();Check(JsonUtility.ToJson(Call(session,"GetObject",id))==before,"object undo restores exact geometry");Check(!Prop<bool>(session,"Dirty"),"undo restores clean state");Undo.PerformRedo();Check(Prop<bool>(session,"Dirty"),"redo restores edit");
   bool rejected=false;try{Call(session,"Transform",id,Vector3.zero,0f,new Vector2(-1,1),1f);}catch(ArgumentException){rejected=true;}Check(rejected,"negative scale rejected");
   Call(session,"WriteDraft");((IDisposable)session).Dispose();session=type.GetMethod("Open").Invoke(null,new object[]{root});Check(Prop<bool>(session,"HasDraft"),"draft survives session/domain lifecycle");Call(session,"WriteDraft");Check(Prop<bool>(session,"HasDraft"),"clean newly opened session preserves unrecovered draft");string draftBytes=File.ReadAllText(Prop<string>(session,"DraftPath"));Call(session,"Transform",id,Vector3.zero,0f,Vector2.one,1.02f);bool draftRejected=false;try{Call(session,"WriteDraft");}catch(IOException){draftRejected=true;}Check(draftRejected&&File.ReadAllText(Prop<string>(session,"DraftPath"))==draftBytes,"new edit cannot overwrite unrecovered same-source draft");Undo.FlushUndoRecordObjects();Undo.PerformUndo();Call(session,"RecoverDraft");Check(Prop<bool>(session,"Dirty"),"draft recovery restores unsaved edit");Call(session,"Save");var saved=ProjectMapStore.Load(root);Check(JsonUtility.ToJson(saved.document.scene.objects.First(o=>o.id!=id))==other,"unrelated object unchanged");Check(JsonUtility.ToJson(Prop<MapData>(session,"Baseline"))==baseline,"baseline unchanged");Check(!Prop<bool>(session,"Dirty"),"saved clean");Check(saved.document.scene.objects.First(o=>o.id==id).height>target.height,"height roundtrip");
   Call(session,"Transform",id,Vector3.zero,0f,Vector2.one,1.01f);Call(session,"WriteDraft");File.AppendAllText(ProjectMapStore.SourcePath(root)," ");string external=File.ReadAllText(ProjectMapStore.SourcePath(root));rejected=false;try{Call(session,"Save");}catch(IOException){rejected=true;}Check(rejected&&File.ReadAllText(ProjectMapStore.SourcePath(root))==external,"external canonical edit rejects save without replacing bytes");
   ((IDisposable)session).Dispose();session=type.GetMethod("Open").Invoke(null,new object[]{root});rejected=false;try{Call(session,"RecoverDraft");}catch(IOException){rejected=true;}Check(rejected&&Prop<bool>(session,"HasDraft"),"changed canonical baseline rejects recovery and retains draft");((IDisposable)session).Dispose();session=type.GetMethod("Open").Invoke(null,new object[]{root});Check(Prop<bool>(session,"HasDraft"),"clean close preserves conflicted recovery draft");Debug.Log("PROJECT_MAP_EDIT_SESSION_TESTS_OK");
  }finally{((IDisposable)session).Dispose();}
 }
}
